const config = {
  plugins: {
    tailwindcss: {},
  },
};
export default config;

@tailwind base;
@tailwind components;
@tailwind utilities;
:root {
  --background: #030712;
  --foreground: #f9fafb;
  --muted: #9ca3af;
  --surface: #0b0f17;
  --glass: rgba(11, 15, 23, 0.75);
  --border: rgba(255, 255, 255, 0.08);
  --border-active: rgba(0, 240, 255, 0.2);
  --accent-cyan: #00f0ff;
  --accent-cyan-deep: #06b6d4;
  --accent-blue: #2563eb;
  --hotspot: #10b981;
}
* {
  border-color: var(--border);
}
html {
  scroll-behavior: smooth;
  overflow-x: hidden;
}
body {
  color: var(--foreground);
  background: var(--background);
  overflow-x: hidden;
  max-width: 100%;
}
@layer utilities {
  .text-balance {
    text-wrap: balance;
  }
  .text-heading-glow {
    background-image: linear-gradient(
      to right,
      #ffffff,
      #e2e8f0,
      #00f0ff
    );
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
  }
  .text-shimmer {
    background-image: linear-gradient(
      90deg,
      #ffffff 0%,
      #00f0ff 28%,
      #06b6d4 50%,
      #2563eb 72%,
      #ffffff 100%
    );
    background-size: 200% auto;
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
    animation: shimmer-wave 3.2s linear infinite;
  }
  .bg-radial-fade {
    background: radial-gradient(
      ellipse 80% 60% at 50% 0%,
      rgba(0, 240, 255, 0.18),
      transparent 70%
    );
  }
  .bg-brand-hero {
    background-image: linear-gradient(
      to bottom,
      #030712,
      #0b0f17,
      #030712
    );
  }
}
@keyframes shimmer-wave {
  0% {
    background-position: 0% center;
  }
  100% {
    background-position: 200% center;
  }
}
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}
@media (max-width: 767px) {
  .animate-glow-pulse {
    animation: none;
  }
}
.pause-anim {
  animation-play-state: paused !important;
}
.drone-zoom-slider {
  writing-mode: vertical-lr;
  direction: rtl;
  appearance: none;
  background: transparent;
  touch-action: none;
}
.drone-zoom-slider::-webkit-slider-runnable-track {
  width: 4px;
  border-radius: 999px;
  background: linear-gradient(to top, #0b0f17, #00f0ff66);
}
.drone-zoom-slider::-webkit-slider-thumb {
  appearance: none;
  width: 14px;
  height: 14px;
  margin-left: -5px;
  border-radius: 999px;
  border: 1px solid rgba(0, 240, 255, 0.8);
  background: #00f0ff;
  box-shadow: 0 0 12px rgba(0, 240, 255, 0.55);
}
.drone-zoom-slider::-moz-range-track {
  width: 4px;
  border-radius: 999px;
  background: #0b0f17;
}
.drone-zoom-slider::-moz-range-thumb {
  width: 14px;
  height: 14px;
  border: 1px solid rgba(0, 240, 255, 0.8);
  border-radius: 999px;
  background: #00f0ff;
  box-shadow: 0 0 12px rgba(0, 240, 255, 0.55);
}
::selection {
  background: rgba(0, 240, 255, 0.28);
  color: #f9fafb;
}
::-webkit-scrollbar {
  width: 10px;
}
::-webkit-scrollbar-track {
  background: var(--background);
}
::-webkit-scrollbar-thumb {
  background: #0b0f17;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 8px;
}
::-webkit-scrollbar-thumb:hover {
  background: #2563eb;
}

