"use client";
import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  type MutableRefObject,
  type ReactNode,
} from "react";
import { useThree } from "@react-three/fiber";
import type { OrbitControls as OrbitControlsImpl } from "three-stdlib";
import { gsap } from "@/lib/gsap";
import { HERO_PLACEMENT, useCompactScene } from "./useCompactScene";
import {
  DEFAULT_CAMERA,
  getHotspot,
  type HotspotId,
} from "./hotspots";
interface CameraFocusContextValue {
  activeHotspot: HotspotId | null;
  isAnimating: boolean;
  setIsAnimating: (value: boolean) => void;
  orbitLocked: boolean;
  setOrbitLocked: (locked: boolean) => void;
  focusHotspot: (id: HotspotId) => void;
  resetView: () => void;
  shouldIgnoreExplore: () => boolean;
}
const CameraFocusContext = createContext<CameraFocusContextValue | null>(null);
export function useCameraFocus() {
  const ctx = useContext(CameraFocusContext);
  if (!ctx) {
    throw new Error("useCameraFocus must be used within CameraFocusProvider");
  }
  return ctx;
}
export function useCameraFocusOptional() {
  return useContext(CameraFocusContext);
}
export function CameraFocusProvider({ children }: { children: ReactNode }) {
  const [activeHotspot, setActiveHotspot] = useState<HotspotId | null>(null);
  const [isAnimating, setIsAnimating] = useState(false);
  const [orbitLocked, setOrbitLocked] = useState(false);
  const ignoreExploreUntil = useRef(0);
  const focusHotspot = useCallback((id: HotspotId) => {
    setActiveHotspot((current) => (current === id ? null : id));
  }, []);
  const resetView = useCallback(() => {
    setActiveHotspot(null);
    ignoreExploreUntil.current = Date.now() + 500;
  }, []);
  const shouldIgnoreExplore = useCallback(
    () => Date.now() < ignoreExploreUntil.current,
    []
  );
  const value = useMemo<CameraFocusContextValue>(
    () => ({
      activeHotspot,
      isAnimating,
      setIsAnimating,
      orbitLocked,
      setOrbitLocked,
      focusHotspot,
      resetView,
      shouldIgnoreExplore,
    }),
    [
      activeHotspot,
      focusHotspot,
      isAnimating,
      orbitLocked,
      resetView,
      shouldIgnoreExplore,
    ]
  );
  return (
    <CameraFocusContext.Provider value={value}>
      {children}
    </CameraFocusContext.Provider>
  );
}
function worldFromLocal(
  local: [number, number, number],
  placement: (typeof HERO_PLACEMENT)["compact" | "desktop"]
): [number, number, number] {
  return [
    placement.position[0] + local[0] * placement.scale,
    placement.position[1] + local[1] * placement.scale,
    placement.position[2] + local[2] * placement.scale,
  ];
}
interface CameraFocusRigProps {
  controlsRef: MutableRefObject<OrbitControlsImpl | null>;
}
export function CameraFocusRig({ controlsRef }: CameraFocusRigProps) {
  const { camera } = useThree();
  const { activeHotspot, setIsAnimating } = useCameraFocus();
  const compact = useCompactScene();
  const timelineRef = useRef<ReturnType<typeof gsap.timeline> | null>(null);
  const didMount = useRef(false);
  const placement = compact ? HERO_PLACEMENT.compact : HERO_PLACEMENT.desktop;
  const restLookAt = useMemo(
    (): [number, number, number] => [
      placement.position[0],
      placement.position[1] + 0.15,
      placement.position[2],
    ],
    [placement]
  );
  useEffect(() => {
    if (!didMount.current) {
      didMount.current = true;
      if (activeHotspot === null) return;
    }
    const controls = controlsRef.current;
    const hotspot = getHotspot(activeHotspot);
    timelineRef.current?.kill();
    setIsAnimating(true);
    const lookTarget = {
      x: restLookAt[0],
      y: restLookAt[1],
      z: restLookAt[2],
    };
    const camTarget = {
      x: DEFAULT_CAMERA[0],
      y: compact ? 0.35 : DEFAULT_CAMERA[1],
      z: DEFAULT_CAMERA[2],
    };
    if (hotspot) {
      const offsetScale = compact ? 0.82 : 1;
      const focus = worldFromLocal(hotspot.position, placement);
      const cam = worldFromLocal(
        [
          hotspot.position[0] + hotspot.cameraOffset[0] * offsetScale,
          hotspot.position[1] + hotspot.cameraOffset[1] * offsetScale,
          hotspot.position[2] + hotspot.cameraOffset[2] * offsetScale,
        ],
        placement
      );
      lookTarget.x = focus[0];
      lookTarget.y = focus[1];
      lookTarget.z = focus[2];
      camTarget.x = cam[0];
      camTarget.y = cam[1];
      camTarget.z = cam[2];
    }
    const look = () => {
      camera.lookAt(lookTarget.x, lookTarget.y, lookTarget.z);
      controls?.target.set(lookTarget.x, lookTarget.y, lookTarget.z);
      controls?.update();
    };
    const tl = gsap.timeline({
      defaults: { ease: "power3.inOut" },
      onComplete: () => {
        look();
        setIsAnimating(false);
      },
    });
    tl.to(camera.position, { ...camTarget, duration: 1.25, onUpdate: look }, 0);
    if (controls) {
      tl.to(
        controls.target,
        { ...lookTarget, duration: 1.25, onUpdate: look },
        0
      );
    }
    timelineRef.current = tl;
    return () => {
      timelineRef.current?.kill();
      timelineRef.current = null;
    };
  }, [
    activeHotspot,
    camera,
    compact,
    controlsRef,
    placement,
    restLookAt,
    setIsAnimating,
  ]);
  return null;
}

"use client";
import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  type MutableRefObject,
  type ReactNode,
} from "react";
import { useFrame, useThree } from "@react-three/fiber";
import { MathUtils, Vector3 } from "three";
import type { OrbitControls as OrbitControlsImpl } from "three-stdlib";
import { gsap } from "@/lib/gsap";
import { useExploreOptional } from "./ExploreSequence";
import { useCameraFocusOptional } from "./CameraFocus";
import { useCompactScene } from "./useCompactScene";
export const ZOOM_MIN_DESKTOP = 2.05;
export const ZOOM_MIN_COMPACT = 2.35;
export const ZOOM_MAX = 11;
const ZOOM_IN_FACTOR = 0.78;
const ZOOM_OUT_FACTOR = 1.28;
const TWEEN_DURATION = 0.42;
interface CameraZoomContextValue {
  distance: number;
  minDistance: number;
  maxDistance: number;
  canZoomIn: boolean;
  canZoomOut: boolean;
  isBusy: boolean;
  isZooming: boolean;
  zoomIn: () => void;
  zoomOut: () => void;
  setDistance: (next: number) => void;
}
const CameraZoomContext = createContext<CameraZoomContextValue | null>(null);
export function useCameraZoom() {
  const ctx = useContext(CameraZoomContext);
  if (!ctx) {
    throw new Error("useCameraZoom must be used within CameraZoomProvider");
  }
  return ctx;
}
export function useCameraZoomOptional() {
  return useContext(CameraZoomContext);
}
function clampDistance(value: number, min: number, max: number) {
  return MathUtils.clamp(value, min, max);
}
interface ZoomCommandBridge {
  command: { id: number; target: number; immediate?: boolean } | null;
  reportDistance: (next: number) => void;
  clearCommand: () => void;
}
const CameraZoomCommandContext = createContext<ZoomCommandBridge | null>(null);
export function CameraZoomProvider({ children }: { children: ReactNode }) {
  const compact = useCompactScene();
  const minDistance = compact ? ZOOM_MIN_COMPACT : ZOOM_MIN_DESKTOP;
  const [distance, setDistanceState] = useState(compact ? 5.2 : 6);
  const [command, setCommand] = useState<{
    id: number;
    target: number;
    immediate?: boolean;
  } | null>(null);
  const commandId = useRef(0);
  const distanceRef = useRef(distance);
  distanceRef.current = distance;
  const explore = useExploreOptional();
  const focus = useCameraFocusOptional();
  const isBusy = Boolean(explore?.isSequencing || focus?.isAnimating);
  const requestDistance = useCallback(
    (next: number, immediate = false) => {
      if (isBusy) return;
      const target = clampDistance(next, minDistance, ZOOM_MAX);
      if (Math.abs(target - distanceRef.current) < 0.02) return;
      commandId.current += 1;
      setCommand({ id: commandId.current, target, immediate });
    },
    [isBusy, minDistance]
  );
  const zoomIn = useCallback(() => {
    requestDistance(distanceRef.current * ZOOM_IN_FACTOR);
  }, [requestDistance]);
  const zoomOut = useCallback(() => {
    requestDistance(distanceRef.current * ZOOM_OUT_FACTOR);
  }, [requestDistance]);
  const setDistance = useCallback(
    (next: number) => {
      requestDistance(next, true);
    },
    [requestDistance]
  );
  const reportDistance = useCallback((next: number) => {
    const rounded = Math.round(next * 40) / 40;
    if (Math.abs(rounded - distanceRef.current) < 0.02) return;
    setDistanceState(rounded);
  }, []);
  const value = useMemo<CameraZoomContextValue>(
    () => ({
      distance,
      minDistance,
      maxDistance: ZOOM_MAX,
      canZoomIn: !isBusy && distance > minDistance + 0.04,
      canZoomOut: !isBusy && distance < ZOOM_MAX - 0.04,
      isBusy,
      isZooming: command !== null,
      zoomIn,
      zoomOut,
      setDistance,
    }),
    [command, distance, isBusy, minDistance, setDistance, zoomIn, zoomOut]
  );
  const commandBridge = useMemo<ZoomCommandBridge>(
    () => ({
      command,
      reportDistance,
      clearCommand: () => setCommand(null),
    }),
    [command, reportDistance]
  );
  return (
    <CameraZoomContext.Provider value={value}>
      <CameraZoomCommandContext.Provider value={commandBridge}>
        {children}
      </CameraZoomCommandContext.Provider>
    </CameraZoomContext.Provider>
  );
}
function useZoomCommand() {
  const ctx = useContext(CameraZoomCommandContext);
  if (!ctx) {
    throw new Error("CameraZoomRig must be used within CameraZoomProvider");
  }
  return ctx;
}
const scratchOffset = new Vector3();
function applyDistance(
  camera: { position: Vector3; lookAt: (x: number, y: number, z: number) => void },
  target: Vector3,
  distance: number,
  controls: OrbitControlsImpl | null
) {
  scratchOffset.copy(camera.position).sub(target);
  if (scratchOffset.lengthSq() < 1e-6) {
    scratchOffset.set(0, 0, 1);
  }
  scratchOffset.setLength(distance);
  camera.position.copy(target).add(scratchOffset);
  camera.lookAt(target.x, target.y, target.z);
  if (controls) {
    controls.target.copy(target);
    controls.update();
  }
}
interface CameraZoomRigProps {
  controlsRef: MutableRefObject<OrbitControlsImpl | null>;
}
export function CameraZoomRig({ controlsRef }: CameraZoomRigProps) {
  const { camera, gl } = useThree();
  const { command, reportDistance, clearCommand } = useZoomCommand();
  const { minDistance } = useCameraZoom();
  const explore = useExploreOptional();
  const focus = useCameraFocusOptional();
  const compact = useCompactScene();
  const tweenRef = useRef<ReturnType<typeof gsap.to> | null>(null);
  const pinchStart = useRef<{ span: number; distance: number } | null>(null);
  const restTarget = useMemo(
    () =>
      compact ? new Vector3(0, 0.2, 0) : new Vector3(2, 0.2, 0),
    [compact]
  );
  const currentTarget = useCallback(() => {
    return controlsRef.current?.target ?? restTarget;
  }, [controlsRef, restTarget]);
  const currentDistance = useCallback(() => {
    return camera.position.distanceTo(currentTarget());
  }, [camera, currentTarget]);
  useFrame(() => {
    if (tweenRef.current || pinchStart.current) return;
    reportDistance(currentDistance());
  });
  useEffect(() => {
    if (!command) return;
    tweenRef.current?.kill();
    const target = currentTarget().clone();
    if (command.immediate) {
      applyDistance(camera, target, command.target, controlsRef.current);
      reportDistance(command.target);
      clearCommand();
      return;
    }
    const proxy = { distance: currentDistance() };
    tweenRef.current = gsap.to(proxy, {
      distance: command.target,
      duration: TWEEN_DURATION,
      ease: "power3.out",
      onUpdate: () => {
        applyDistance(camera, target, proxy.distance, controlsRef.current);
        reportDistance(proxy.distance);
      },
      onComplete: () => {
        applyDistance(camera, target, command.target, controlsRef.current);
        reportDistance(command.target);
        clearCommand();
      },
    });
    return () => {
      tweenRef.current?.kill();
      tweenRef.current = null;
    };
  }, [camera, clearCommand, command, controlsRef, currentDistance, currentTarget, reportDistance]);
  useEffect(() => {
    if (explore?.isSequencing || focus?.isAnimating) {
      tweenRef.current?.kill();
      pinchStart.current = null;
    }
  }, [explore?.isSequencing, focus?.isAnimating]);
  useEffect(() => {
    const el = gl.domElement;
    const busy = () => Boolean(explore?.isSequencing || focus?.isAnimating);
    const touchSpan = (event: TouchEvent) => {
      const [a, b] = [event.touches[0], event.touches[1]];
      if (!a || !b) return 0;
      return Math.hypot(a.clientX - b.clientX, a.clientY - b.clientY);
    };
    const onTouchStart = (event: TouchEvent) => {
      if (event.touches.length !== 2 || busy()) {
        pinchStart.current = null;
        return;
      }
      tweenRef.current?.kill();
      pinchStart.current = {
        span: touchSpan(event),
        distance: currentDistance(),
      };
    };
    const onTouchMove = (event: TouchEvent) => {
      const start = pinchStart.current;
      if (!start || event.touches.length !== 2 || busy()) return;
      event.preventDefault();
      const span = touchSpan(event);
      if (span < 8 || start.span < 8) return;
      const next = clampDistance(
        start.distance * (start.span / span),
        minDistance,
        ZOOM_MAX
      );
      applyDistance(camera, currentTarget().clone(), next, controlsRef.current);
      reportDistance(next);
    };
    const onTouchEnd = () => {
      pinchStart.current = null;
    };
    el.addEventListener("touchstart", onTouchStart, { passive: true });
    el.addEventListener("touchmove", onTouchMove, { passive: false });
    el.addEventListener("touchend", onTouchEnd);
    el.addEventListener("touchcancel", onTouchEnd);
    return () => {
      el.removeEventListener("touchstart", onTouchStart);
      el.removeEventListener("touchmove", onTouchMove);
      el.removeEventListener("touchend", onTouchEnd);
      el.removeEventListener("touchcancel", onTouchEnd);
    };
  }, [
    camera,
    controlsRef,
    currentDistance,
    currentTarget,
    explore?.isSequencing,
    focus?.isAnimating,
    gl.domElement,
    minDistance,
    reportDistance,
  ]);
  return null;
}

"use client";
import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  type MutableRefObject,
  type ReactNode,
} from "react";
import { useThree } from "@react-three/fiber";
import { Radar, RotateCcw } from "lucide-react";
import type { Group } from "three";
import type { OrbitControls as OrbitControlsImpl } from "three-stdlib";
import { gsap } from "@/lib/gsap";
import { Button } from "@/components/ui/Button";
import { cn } from "@/lib/utils";
import { HERO_PLACEMENT, useCompactScene } from "./useCompactScene";
export type ExploreState = "idle" | "flying" | "exploring" | "returning";
interface ExploreContextValue {
  state: ExploreState;
  isBusy: boolean;
  isSequencing: boolean;
  trigger: () => void;
  complete: () => void;
}
const ExploreContext = createContext<ExploreContextValue | null>(null);
export function useExplore() {
  const ctx = useContext(ExploreContext);
  if (!ctx) {
    throw new Error("useExplore must be used within ExploreProvider");
  }
  return ctx;
}
export function useExploreOptional() {
  return useContext(ExploreContext);
}
export function ExploreProvider({ children }: { children: ReactNode }) {
  const [state, setState] = useState<ExploreState>("idle");
  const stateRef = useRef(state);
  stateRef.current = state;
  const trigger = useCallback(() => {
    const current = stateRef.current;
    if (current === "flying" || current === "returning") return;
    setState(current === "idle" ? "flying" : "returning");
  }, []);
  const complete = useCallback(() => {
    const current = stateRef.current;
    if (current === "flying") setState("exploring");
    if (current === "returning") setState("idle");
  }, []);
  const value = useMemo<ExploreContextValue>(
    () => ({
      state,
      isBusy: state === "flying" || state === "returning",
      isSequencing: state === "flying" || state === "returning",
      trigger,
      complete,
    }),
    [state, trigger, complete]
  );
  return (
    <ExploreContext.Provider value={value}>{children}</ExploreContext.Provider>
  );
}
const REST_CAMERA = { x: 0, y: 0, z: 6 } as const;
const LOOK_AT_COMPACT = { x: 0, y: 0.2, z: 0 } as const;
const FLY_WAYPOINT_COMPACT = { x: 3.35, y: 1.75, z: 5.6 } as const;
const FLY_CLOSE_COMPACT = { x: 1.55, y: 0.72, z: 3.55 } as const;
interface ExploreRigProps {
  subjectRef: MutableRefObject<Group | null>;
  controlsRef: MutableRefObject<OrbitControlsImpl | null>;
}
export function ExploreRig({ subjectRef, controlsRef }: ExploreRigProps) {
  const { camera } = useThree();
  const { state, complete } = useExplore();
  const compact = useCompactScene();
  const timelineRef = useRef<ReturnType<typeof gsap.timeline> | null>(null);
  const lookAt = useMemo(
    () =>
      compact
        ? LOOK_AT_COMPACT
        : {
            x: HERO_PLACEMENT.desktop.position[0],
            y: HERO_PLACEMENT.desktop.position[1] + 0.15,
            z: HERO_PLACEMENT.desktop.position[2],
          },
    [compact]
  );
  const flyWaypoint = compact
    ? FLY_WAYPOINT_COMPACT
    : { x: 4.15, y: 1.7, z: 5.4 };
  const flyClose = compact
    ? FLY_CLOSE_COMPACT
    : { x: 3.15, y: 0.7, z: 3.7 };
  useEffect(() => {
    const subject = subjectRef.current;
    const controls = controlsRef.current;
    if (!subject) return;
    timelineRef.current?.kill();
    const look = () => {
      camera.lookAt(lookAt.x, lookAt.y, lookAt.z);
      controls?.update();
    };
    if (state === "flying") {
      const tl = gsap.timeline({
        defaults: { ease: "power3.inOut" },
        onComplete: () => {
          controls?.target.set(lookAt.x, lookAt.y, lookAt.z);
          controls?.update();
          complete();
        },
      });
      tl.to(
        camera.position,
        { ...flyWaypoint, duration: 1.15, onUpdate: look },
        0
      );
      tl.to(
        camera.position,
        { ...flyClose, duration: 1.25, onUpdate: look },
        0.95
      );
      tl.to(
        subject.rotation,
        { y: subject.rotation.y + Math.PI * 2, duration: 2.4 },
        0
      );
      tl.to(subject.position, { y: 0.28, duration: 2.4 }, 0);
      tl.to(subject.scale, { x: 1.08, y: 1.08, z: 1.08, duration: 2.4 }, 0);
      timelineRef.current = tl;
    }
    if (state === "returning") {
      const tl = gsap.timeline({
        defaults: { ease: "power3.inOut" },
        onComplete: () => {
          controls?.target.set(lookAt.x, lookAt.y, lookAt.z);
          controls?.update();
          complete();
        },
      });
      tl.to(
        camera.position,
        { ...REST_CAMERA, duration: 1.8, onUpdate: look },
        0
      );
      tl.to(subject.position, { y: 0, duration: 1.8 }, 0);
      tl.to(subject.scale, { x: 1, y: 1, z: 1, duration: 1.8 }, 0);
      timelineRef.current = tl;
    }
    return () => {
      timelineRef.current?.kill();
      timelineRef.current = null;
    };
  }, [camera, complete, controlsRef, flyClose, flyWaypoint, lookAt, state, subjectRef]);
  return null;
}
const LABELS: Record<ExploreState, string> = {
  idle: "EXPLORE",
  flying: "FLY",
  exploring: "RESET",
  returning: "FLY",
};
export function ExploreButton({ className }: { className?: string }) {
  const { state, isBusy, trigger } = useExplore();
  const label = LABELS[state];
  const Icon = state === "exploring" ? RotateCcw : Radar;
  return (
    <Button
      type="button"
      variant={state === "exploring" ? "secondary" : "primary"}
      disabled={isBusy}
      onClick={trigger}
      aria-label={
        state === "exploring"
          ? "Reset camera"
          : "Fly the camera in and rotate the model"
      }
      aria-busy={isBusy}
      className={cn(
        "pointer-events-auto min-w-[9.5rem] tracking-[0.18em] uppercase",
        isBusy && "opacity-80",
        className
      )}
    >
      <Icon
        className={cn("h-4 w-4", isBusy && "animate-spin")}
        aria-hidden
      />
      {label}
