import { HOTSPOTS, type HotspotDefinition } from "./hotspots";
const DRONE_MODEL_PATH = "https://raw.githubusercontent.com/basitnayab1/TechnoAi/cursor/brand-colors-ae31/public/models/drone.glb";
const BASE_SCALE = 1;
const HOVER_SCALE = 1.08;
const TARGET_SIZE = 2.6;
function HeroShape() {
  const outerRef = useRef<Group>(null);
  const modelRef = useRef<Group>(null);
  const { scene } = useGLTF(DRONE_MODEL_PATH);
  const [hovered, setHovered] = useState(false);
  const explore = useExploreOptional();
  const focus = useCameraFocusOptional();
  const compact = useCompactScene();
  const placement = compact ? HERO_PLACEMENT.compact : HERO_PLACEMENT.desktop;
  const isFocused = Boolean(focus?.activeHotspot);
  const model = useMemo(() => {
    const clone = scene.clone(true);
    const box = new Box3().setFromObject(clone);
    const size = box.getSize(new Vector3());
    const center = box.getCenter(new Vector3());
    clone.position.sub(center);
    clone.traverse((child) => {
      if ("isMesh" in child && child.isMesh) {
        child.castShadow = true;
        child.receiveShadow = true;
      }
    });
    const maxDim = Math.max(size.x, size.y, size.z);
    const normalizedScale = TARGET_SIZE / maxDim;
    return { node: clone, normalizedScale };
  }, [scene]);
  useFrame((_, delta) => {
    const outer = outerRef.current;
    const model3d = modelRef.current;
    if (!outer || !model3d) return;
    if (!explore?.isSequencing && !isFocused) {
      outer.rotation.y += delta * 0.22;
    }
    const currentMultiplier = model3d.scale.x / model.normalizedScale;
    const nextMultiplier = MathUtils.lerp(
      currentMultiplier,
      hovered && !isFocused ? HOVER_SCALE : BASE_SCALE,
      delta * 6
    );
    const scale = model.normalizedScale * nextMultiplier;
    model3d.scale.setScalar(scale);
  });
  return (
    <group position={placement.position} scale={placement.scale}>
      <Float
        speed={isFocused ? 0 : 1.6}
        rotationIntensity={isFocused ? 0 : 0.5}
        floatIntensity={isFocused ? 0 : 1.1}
      >
        <group ref={outerRef} rotation={[0.08, 0.55, 0]}>
          <group
            ref={modelRef}
            scale={model.normalizedScale}
            onPointerOver={(event) => {
              event.stopPropagation();
              setHovered(true);
              document.body.style.cursor = "pointer";
            }}
            onPointerOut={(event) => {
              event.stopPropagation();
              setHovered(false);
              document.body.style.cursor = "auto";
            }}
          >
            <primitive object={model.node} />
          </group>
          {HOTSPOTS.map((hotspot) => (
            <Hotspot
              key={hotspot.id}
              hotspot={hotspot}
              isActive={focus?.activeHotspot === hotspot.id}
              onSelect={() => focus?.focusHotspot(hotspot.id)}
              onReset={() => focus?.resetView()}
              onLockOrbit={(locked) => focus?.setOrbitLocked(locked)}
            />
          ))}
        </group>
      </Float>
    </group>
  );
}
function Hotspot({
  hotspot,
  isActive,
  onSelect,
  onReset,
  onLockOrbit,
}: {
  hotspot: HotspotDefinition;
  isActive: boolean;
  onSelect: () => void;
  onReset: () => void;
  onLockOrbit: (locked: boolean) => void;
}) {
  const [hovered, setHovered] = useState(false);
  const highlighted = hovered || isActive;
  const lock = (next: boolean) => {
    onLockOrbit(next);
