        onPointerOut={(event) => {
          event.stopPropagation();
          setHovered(false);
          lock(false);
        }}
        onPointerDown={(event) => {
          event.stopPropagation();
        }}
        onClick={(event) => {
          event.stopPropagation();
          onSelect();
        }}
      >
        <sphereGeometry args={[0.42, 16, 16]} />
