            )}
          >
            <span
              className={cn(
                "pointer-events-none absolute -inset-1 rounded-full border border-[#10B981]/50 animate-ping",
                isActive && "pause-anim"
              )}
            />
            <span className="relative">{hotspot.code}</span>
          </button>
          {isActive && (
            <div
