                }}
                className="absolute right-2 top-2 flex h-6 w-6 items-center justify-center rounded-full border border-[rgba(255,255,255,0.08)] text-[#9CA3AF] hover:border-[rgba(0,240,255,0.2)] hover:text-[#00F0FF]"
