  const reduce = useReducedMotion();
  return {
    reduce: Boolean(reduce),
    fade: reduce ? { initial: { opacity: 0 }, animate: { opacity: 1 } } : fadeUp,
    spring: reduce ? { duration: 0.2 } : springSoft,
  };
}

